# Remediation is applicable only in certain platforms if ( ! ( dpkg-query --show --showformat='${db:Status-Status}
' 'nftables' 2>/dev/null | grep -q '^installed' ) && ! ( dpkg-query --show --showformat='${db:Status-Status}
' 'ufw' 2>/dev/null | grep -q '^installed' ) && dpkg-query --show --showformat='${db:Status-Status}
' 'iptables' 2>/dev/null | grep -q '^installed' ); then
DEBIAN_FRONTEND=noninteractive apt-get install -y "iptables-persistent" sed -i 's/^:INPUT ACCEPT.*/:INPUT DROP [0:0]/g' /etc/iptables/rules.v6
else >&2 echo 'Remediation is not applicable, nothing was done' fi

# Remediation is applicable only in certain platforms if ( ! ( dpkg-query --show --showformat='${db:Status-Status}
' 'nftables' 2>/dev/null | grep -q '^installed' ) && ! ( dpkg-query --show --showformat='${db:Status-Status}
' 'ufw' 2>/dev/null | grep -q '^installed' ) && dpkg-query --show --showformat='${db:Status-Status}
' 'iptables' 2>/dev/null | grep -q '^installed' ); then
if [ "$(sysctl -n net.ipv6.conf.all.disable_ipv6)" -eq 0 ]; then # IPv6 is not disabled, so run the script ip6tables -A INPUT -i lo -j ACCEPT ip6tables -A OUTPUT -o lo -j ACCEPT ip6tables -A INPUT -s ::1 -j DROP fi
else >&2 echo 'Remediation is not applicable, nothing was done' fi

# Remediation is applicable only in certain platforms if ( ! ( dpkg-query --show --showformat='${db:Status-Status}
' 'nftables' 2>/dev/null | grep -q '^installed' ) && ! ( dpkg-query --show --showformat='${db:Status-Status}
' 'ufw' 2>/dev/null | grep -q '^installed' ) && dpkg-query --show --showformat='${db:Status-Status}
' 'iptables' 2>/dev/null | grep -q '^installed' ); then
iptables -A INPUT -i lo -j ACCEPT iptables -A OUTPUT -o lo -j ACCEPT iptables -A INPUT -s 127.0.0.0/8 -j DROP
else >&2 echo 'Remediation is not applicable, nothing was done' fi

# Remediation is applicable only in certain platforms if dpkg-query --show --showformat='${db:Status-Status}
' 'iptables' 2>/dev/null | grep -q '^installed' && { ( ! ( dpkg-query --show --showformat='${db:Status-Status}
' 'nftables' 2>/dev/null | grep -q '^installed' ) && ! ( dpkg-query --show --showformat='${db:Status-Status}
' 'ufw' 2>/dev/null | grep -q '^installed' ) ); }; then
sed -i 's/^:INPUT ACCEPT.*/:INPUT DROP [0:0]/g' /etc/sysconfig/iptables
else >&2 echo 'Remediation is not applicable, nothing was done' fi

Rule.description:
Base chain policy is the default verdict that will be applied to packets reaching the end of
the chain. There are two policies: accept (Default) and drop. If the policy is set to accept,
the firewall will accept any packet that is not configured to be denied and the packet will
continue traversing the network stack.

{% if 'ubuntu' in product %}
Run the following commands and verify that base chains contain a policy of DROP.

$ nft list ruleset | grep 'hook input'
type filter hook input priority 0; policy drop;
$ nft list ruleset | grep 'hook forward'
type filter hook forward priority 0; policy drop;
$ nft list ruleset | grep 'hook output'
type filter hook output priority 0; policy drop;

Rule.fix:
include disable_bluetooth

class disable_bluetooth {
  service {'bluetooth':
    enable => false,
    ensure => 'stopped',
  }
}

include remove_autofs

class remove_autofs {
  package { 'autofs':
    ensure => 'purged',
  }
}

include disable_autofs

class disable_autofs {
  service {'autofs':
    enable => false,
    ensure => 'stopped',
  }
}

# Remediation is applicable only in certain platforms if ! ( [ -f /.dockerenv ] || [ -f /run/.containerenv ] ) && { findmnt --kernel "/home" > /dev/null || findmnt --fstab "/home" > /dev/null; }; then
function perform_remediation {
# the mount point /home has to be defined in /etc/fstab # before this remediation can be executed. In case it is not defined, the # remediation aborts and no changes regarding the mount point are done. mount_point_match_regexp="$(printf "^[[:space:]]*[^#].*[[:space:]]%s[[:space:]]" "/home")"
grep "$mount_point_match_regexp" -q /etc/fstab \ || { echo "The mount point '/home' is not even in /etc/fstab, so we can't set up mount options" >&2; echo "Not remediating, because there is no record of /home in /etc/fstab" >&2; return 1; }
mount_point_match_regexp="$(printf "^[[:space:]]*[^#].*[[:space:]]%s[[:space:]]" /home)"
# If the mount point is not in /etc/fstab, get previous mount options from /etc/mtab if ! grep -q "$mount_point_match_regexp" /etc/fstab; then # runtime opts without some automatic kernel/userspace-added defaults previous_mount_opts=$(grep "$mount_point_match_regexp" /etc/mtab | head -1 | awk '{print $4}' \ | sed -E "s/(rw|defaults|seclabel|nodev)(,|$)//g;s/,$//") [ "$previous_mount_opts" ] && previous_mount_opts+="," # In iso9660 filesystems mtab could describe a "blocksize" value, this should be reflected in # fstab as "block". The next variable is to satisfy shellcheck SC2050. fs_type="" if [ "$fs_type" == "iso9660" ] ; then previous_mount_opts=$(sed 's/blocksize=/block=/' <<< "$previous_mount_opts") fi echo " /home defaults,${previous_mount_opts}nodev 0 0" >> /etc/fstab # If the mount_opt option is not already in the mount point's /etc/fstab entry, add it elif ! grep "$mount_point_match_regexp" /etc/fstab | grep -q "nodev"; then previous_mount_opts=$(grep "$mount_point_match_regexp" /etc/fstab | awk '{print $4}') sed -i "s|\(${mount_point_match_regexp}.*${previous_mount_opts}\)|\1,nodev|" /etc/fstab fi
if mkdir -p "/home"; then if mountpoint -q "/home"; then mount -o remount --target "/home" fi fi }
perform_remediation
else >&2 echo 'Remediation is not applicable, nothing was done' fi

